//! PQ-AUTH specification: ML-DSA-65 (FIPS 204), the post-quantum half of the composite CA
//! signature (PROTOCOL §15.14; decision D11, finding AP-5 of review 0007).
//!
//! - The fleet's verifier (`zt_crypto::mldsa`, `RustCrypto` `ml-dsa`, exact pin) passes the NIST
//!   ACVP key-generation vectors and the Wycheproof verification and signing vectors
//!   (`tests/vectors/mldsa65.txt`, regenerated by `generate_mldsa65.py`).
//! - The independent `libcrux-ml-dsa` (test-only) agrees with it on key generation, on every
//!   vector, and on mutated signatures no vector covers (the bug classes of CVE-2026-24850 and
//!   GHSA-h37v-hp6w-2pp8: hint encoding and `use_hint`).
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::indexing_slicing,
    clippy::arithmetic_side_effects,
    clippy::cast_possible_truncation,
    missing_docs
)]

use sha2::{Digest, Sha256};
use zt_crypto::mldsa::{self, MlDsa65SigningKey, PUBLIC_KEY_LEN, SIGNATURE_LEN};

const VECTORS: &str = include_str!("vectors/mldsa65.txt");

fn unhex(field: &str) -> Vec<u8> {
    if field == "-" {
        Vec::new()
    } else {
        hex::decode(field).unwrap()
    }
}

fn seed(field: &str) -> [u8; 32] {
    unhex(field).try_into().unwrap()
}

// --- the oracle: libcrux-ml-dsa -------------------------------------------------------

fn oracle_public_key(seed: [u8; 32]) -> Vec<u8> {
    libcrux_ml_dsa::ml_dsa_65::generate_key_pair(seed)
        .verification_key
        .as_slice()
        .to_vec()
}

fn oracle_verify(pk: &[u8], msg: &[u8], ctx: &[u8], sig: &[u8]) -> bool {
    let Ok(pk) = <[u8; PUBLIC_KEY_LEN]>::try_from(pk) else {
        return false;
    };
    let Ok(sig) = <[u8; SIGNATURE_LEN]>::try_from(sig) else {
        return false;
    };
    let pk = libcrux_ml_dsa::ml_dsa_65::MLDSA65VerificationKey::new(pk);
    let sig = libcrux_ml_dsa::ml_dsa_65::MLDSA65Signature::new(sig);
    libcrux_ml_dsa::ml_dsa_65::verify(&pk, msg, ctx, &sig).is_ok()
}

// --- vectors ---------------------------------------------------------------------------

#[test]
fn ml_dsa_65_sizes_are_those_of_fips_204() {
    assert_eq!(PUBLIC_KEY_LEN, 1_952);
    assert_eq!(SIGNATURE_LEN, 3_309);
    let key = MlDsa65SigningKey::from_seed(&[7; 32]);
    assert_eq!(key.public_key().len(), 1_952);
    assert_eq!(key.sign(b"m", b"ctx", &[0; 32]).unwrap().len(), 3_309);
}

#[test]
fn key_generation_passes_the_acvp_vectors_and_agrees_with_the_oracle() {
    let mut n = 0;
    for line in VECTORS.lines().filter(|l| l.starts_with("keygen ")) {
        let f: Vec<&str> = line.split(' ').collect();
        let pk = MlDsa65SigningKey::from_seed(&seed(f[1])).public_key();
        assert_eq!(hex::encode(Sha256::digest(&pk)), f[2], "keygen {}", f[1]);
        assert_eq!(pk, oracle_public_key(seed(f[1])));
        n += 1;
    }
    assert_eq!(n, 25);
}

#[test]
fn verification_passes_the_wycheproof_vectors_and_agrees_with_the_oracle() {
    let (mut valid, mut invalid) = (0, 0);
    let mut pk = Vec::new();
    for line in VECTORS.lines() {
        let f: Vec<&str> = line.split(' ').collect();
        match f[0] {
            "pk" => pk = unhex(f[1]),
            "verify" => {
                let (ctx, msg, sig) = (unhex(f[3]), unhex(f[4]), unhex(f[5]));
                let ours = mldsa::verify(&pk, &msg, &ctx, &sig);
                assert_eq!(ours, f[2] == "valid", "tcId {}", f[1]);
                assert_eq!(
                    oracle_verify(&pk, &msg, &ctx, &sig),
                    ours,
                    "oracle tcId {}",
                    f[1]
                );
                if ours { valid += 1 } else { invalid += 1 }
            }
            "badpk" => {
                assert!(!mldsa::verify(
                    &unhex(f[2]),
                    &unhex(f[3]),
                    &[],
                    &unhex(f[4])
                ));
            }
            _ => {}
        }
    }
    assert_eq!((valid, invalid), (79, 41));
}

#[test]
fn deterministic_signing_passes_the_wycheproof_vectors() {
    let mut n = 0;
    for line in VECTORS.lines().filter(|l| l.starts_with("sign ")) {
        let f: Vec<&str> = line.split(' ').collect();
        let key = MlDsa65SigningKey::from_seed(&seed(f[1]));
        // The deterministic variant of FIPS 204 is `rnd = 0^32`.
        let sig = key.sign(&unhex(f[3]), &unhex(f[2]), &[0; 32]).unwrap();
        assert_eq!(hex::encode(Sha256::digest(&sig)), f[4]);
        n += 1;
    }
    assert_eq!(n, 12);
}

// --- behaviour -------------------------------------------------------------------------

/// Hedged signing: different `rnd`, different signatures, all valid; the context separates.
#[test]
fn hedged_signatures_differ_and_the_context_separates() {
    let key = MlDsa65SigningKey::from_seed(&[3; 32]);
    let pk = key.public_key();
    let a = key.sign(b"message", b"TCN-cert-v2", &[1; 32]).unwrap();
    let b = key.sign(b"message", b"TCN-cert-v2", &[2; 32]).unwrap();
    assert_ne!(a, b);
    for sig in [&a, &b] {
        assert!(mldsa::verify(&pk, b"message", b"TCN-cert-v2", sig));
        assert!(oracle_verify(&pk, b"message", b"TCN-cert-v2", sig));
        assert!(!mldsa::verify(&pk, b"message", b"TCN-cert-v1", sig));
        assert!(!mldsa::verify(&pk, b"message", b"", sig));
        assert!(!mldsa::verify(&pk, b"messagE", b"TCN-cert-v2", sig));
    }
    assert!(key.sign(b"m", &[0; 256], &[0; 32]).is_err());
    assert!(!mldsa::verify(&pk, b"m", &[0; 256], &a));
}

/// A (Parsing): wrong lengths of key and signature are refused without a panic.
#[test]
fn wrong_lengths_are_refused() {
    let key = MlDsa65SigningKey::from_seed(&[4; 32]);
    let pk = key.public_key();
    let sig = key.sign(b"m", b"c", &[0; 32]).unwrap();
    for len in [0, 1, SIGNATURE_LEN - 1, SIGNATURE_LEN + 1, 65_535] {
        let mut s = sig.clone();
        s.resize(len, 0);
        assert!(!mldsa::verify(&pk, b"m", b"c", &s), "{len}");
    }
    for len in [0, PUBLIC_KEY_LEN - 1, PUBLIC_KEY_LEN + 1] {
        let mut k = pk.clone();
        k.resize(len, 0);
        assert!(!mldsa::verify(&k, b"m", b"c", &sig), "{len}");
    }
}

/// A (Malleability, differential): every single-byte mutation of the hint area and of the
/// boundaries of `c̃` and `z`, plus pseudo-random mutations, is judged the same way by both
/// implementations, and never accepted by ours.
#[test]
fn mutated_signatures_are_judged_alike_and_never_accepted() {
    let key = MlDsa65SigningKey::from_seed(&[5; 32]);
    let pk = key.public_key();
    let msg = b"TCN client certificate v2\0TBS";
    let sig = key.sign(msg, b"TCN-cert-v2", &[9; 32]).unwrap();
    assert!(mldsa::verify(&pk, msg, b"TCN-cert-v2", &sig));
    // The hint area is the last ω + k = 55 + 6 = 61 bytes of an ML-DSA-65 signature.
    let mut positions: Vec<usize> = (SIGNATURE_LEN - 61..SIGNATURE_LEN).collect();
    positions.extend([0, 1, 47, 48, 49, 50, 1_000, 2_000, 3_000]);
    let mut state = 0x9e37_79b9_7f4a_7c15_u64;
    for _ in 0..64 {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        positions.push((state % SIGNATURE_LEN as u64) as usize);
    }
    for pos in positions {
        for delta in [0x01_u8, 0x80, 0xff] {
            let mut m = sig.clone();
            m[pos] ^= delta;
            let ours = mldsa::verify(&pk, msg, b"TCN-cert-v2", &m);
            assert!(!ours, "mutation at {pos} accepted");
            assert_eq!(
                oracle_verify(&pk, msg, b"TCN-cert-v2", &m),
                ours,
                "at {pos}"
            );
        }
    }
    // CVE-2026-24850 class: a repeated hint index (the last index of the first polynomial
    // written twice) must be refused by both.
    let hints = &sig[SIGNATURE_LEN - 61..];
    let first_count = usize::from(hints[55]);
    if first_count >= 2 {
        let mut m = sig.clone();
        let base = SIGNATURE_LEN - 61;
        m[base + first_count - 1] = m[base + first_count - 2];
        assert!(!mldsa::verify(&pk, msg, b"TCN-cert-v2", &m));
        assert!(!oracle_verify(&pk, msg, b"TCN-cert-v2", &m));
    }
}

/// The signing key never shows in `Debug`.
#[test]
fn the_signing_key_debug_is_redacted() {
    let key = MlDsa65SigningKey::from_seed(&[0x41; 32]);
    assert_eq!(format!("{key:?}"), "MlDsa65SigningKey(<redacted>)");
}
